/* Dedicated linear planar EM model, solver-format parser and independent
 * scientific receipts. Gmsh/GetDP alone perform FEM. No process, Job, Dataset,
 * resource, configuration or Workspace ownership lives here. GPL-3.0-or-later. */
#include <tcl.h>
#include <algorithm>
#include <array>
#include <cmath>
#include <cctype>
#include <cstdlib>
#include <iomanip>
#include <limits>
#include <map>
#include <set>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
#include "em_templates.h"
namespace {
constexpr double pi=3.14159265358979323846,mu0=4e-7*pi,eps0=8.8541878188e-12;
using V=std::array<double,3>;using Key=std::array<long long,9>;
Tcl_Obj*S(const std::string&s){return Tcl_NewStringObj(s.data(),s.size());}
void put(Tcl_Obj*d,const std::string&k,Tcl_Obj*v){Tcl_DictObjPut(nullptr,d,S(k),v);}
Tcl_Obj*get(Tcl_Interp*ip,Tcl_Obj*d,const std::string&k){Tcl_Obj*v=nullptr;if(Tcl_DictObjGet(ip,d,S(k),&v)!=TCL_OK)throw std::runtime_error("Model must be an inert dictionary");return v;}
std::string str(Tcl_Interp*ip,Tcl_Obj*d,const std::string&k,std::string fallback=""){auto v=get(ip,d,k);return v?Tcl_GetString(v):fallback;}
double real(Tcl_Interp*ip,Tcl_Obj*d,const std::string&k,double low,double high){auto p=get(ip,d,k);double v;if(!p||Tcl_GetDoubleFromObj(ip,p,&v)!=TCL_OK||!std::isfinite(v)||v<low||v>high)throw std::runtime_error(k+": finite numeric value outside allowed physical domain");return v;}
std::string number(double v){std::ostringstream o;o<<std::setprecision(17)<<v;return o.str();}
void replace(std::string&s,const std::string&key,const std::string&value){auto p=s.find(key);if(p==std::string::npos)throw std::runtime_error("Missing native model template key");s.replace(p,key.size(),value);}
struct Model{std::string kind,id;double half,height,h,r=.005,j=1e6,mur=1,voltage=1,epsr=1;bool magnetic()const{return kind=="magnetostatic_2d";}};
Model model(Tcl_Interp*ip,Tcl_Obj*d){Model m;m.kind=str(ip,d,"kind");m.id=str(ip,d,"model_id");if(m.kind!="magnetostatic_2d"&&m.kind!="electrostatic_2d")throw std::runtime_error("Only linear planar static 2D physics is supported");if(str(ip,d,"formulation")!="planar_2d")throw std::runtime_error("Only planar_2d formulation is supported");if(m.id.empty()||m.id.size()>81||!std::isalpha((unsigned char)m.id[0])||m.id.find_first_not_of("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.-")!=std::string::npos)throw std::runtime_error("Invalid scientific model identity");
 Tcl_DictSearch it;Tcl_Obj*k,*v;int done;if(Tcl_DictObjFirst(ip,d,&it,&k,&v,&done)!=TCL_OK)throw std::runtime_error("Invalid model dictionary");std::set<std::string>allowed={"kind","model_id","formulation","half_width_m","height_m","mesh_size_m","radius_m","current_density_A_m2","mu_r","voltage_V","eps_r"};for(;!done;Tcl_DictObjNext(&it,&k,&v,&done))if(!allowed.count(Tcl_GetString(k))){Tcl_DictObjDone(&it);throw std::runtime_error("Unknown scientific model field; solver paths belong to Runtime Configuration");}Tcl_DictObjDone(&it);
 m.half=real(ip,d,"half_width_m",.001,2);m.height=real(ip,d,"height_m",.001,2);m.h=real(ip,d,"mesh_size_m",.00001,.2);if(m.h>.6*std::min(m.half,m.height)||4*m.half*m.height/(m.h*m.h)>6000)throw std::runtime_error("Mesh exceeds bounded element/resolution policy");if(m.magnetic()){m.r=real(ip,d,"radius_m",.00001,.35*std::min(m.half,m.height));if(m.h>m.r/2)throw std::runtime_error("Mesh must resolve conductor radius by at least two elements");m.j=real(ip,d,"current_density_A_m2",.001,1e9);m.mur=real(ip,d,"mu_r",1e-5,1e5);}else{m.voltage=real(ip,d,"voltage_V",1e-8,1e6);m.epsr=real(ip,d,"eps_r",1e-4,1e5);}return m;}
Tcl_Obj*modelDict(const Model&m){auto d=Tcl_NewDictObj();put(d,"kind",S(m.kind));put(d,"model_id",S(m.id));put(d,"formulation",S("planar_2d"));for(auto p:{std::pair<const char*,double>{"half_width_m",m.half},{"height_m",m.height},{"mesh_size_m",m.h},{"radius_m",m.r},{"current_density_A_m2",m.j},{"mu_r",m.mur},{"voltage_V",m.voltage},{"eps_r",m.epsr}})put(d,p.first,Tcl_NewDoubleObj(p.second));return d;}
Tcl_Obj*prepare(const Model&m){std::ostringstream o;o<<std::setprecision(17);o<<"// SI meters; exact original bounded geometry\nSetFactory(\"Built-in\");\nh="<<m.h<<";\n";std::vector<V>p={V{-m.half,-m.height/2,0},V{m.half,-m.height/2,0},V{m.half,m.height/2,0},V{-m.half,m.height/2,0}};if(m.magnetic())p.insert(p.end(),{V{0,0,0},V{m.r,0,0},V{0,m.r,0},V{-m.r,0,0},V{0,-m.r,0}});for(size_t i=0;i<p.size();++i)o<<"Point("<<i+1<<")={"<<p[i][0]<<","<<p[i][1]<<",0,h};\n";for(int i=1;i<=4;++i)o<<"Line("<<i<<")={"<<i<<","<<(i==4?1:i+1)<<"};\n";o<<"Curve Loop(10)={1,2,3,4};\n";if(m.magnetic())o<<"Circle(5)={6,5,7}; Circle(6)={7,5,8}; Circle(7)={8,5,9}; Circle(8)={9,5,6};\nCurve Loop(20)={5,6,7,8};\nPlane Surface(101)={10,20}; Plane Surface(102)={20};\nPhysical Surface(\"Air\",101)={101}; Physical Surface(\"Conductor\",102)={102};\nPhysical Curve(\"OuterBoundary\",110)={1,2,3,4};\n";else o<<"Plane Surface(101)={10}; Physical Surface(\"Dielectric\",101)={101};\nPhysical Curve(\"LowPotential\",120)={4}; Physical Curve(\"HighPotential\",121)={2};\n";o<<"Mesh.MeshSizeMin="<<m.h/2<<"; Mesh.MeshSizeMax=h;\nMesh.Algorithm=6; Mesh.SaveAll=0;\n";
 std::string pro=m.magnetic()?magnetic_pro:electro_pro;replace(pro,"@INTEGRATION@",integration);if(m.magnetic()){replace(pro,"@MU@",number(m.mur));replace(pro,"@CURRENT@",number(m.j));}else{replace(pro,"@EPS@",number(m.epsr));replace(pro,"@VOLTAGE@",number(m.voltage));}auto d=Tcl_NewDictObj(),inputs=Tcl_NewDictObj();put(inputs,"model.geo",S(o.str()));put(inputs,"model.pro",S(pro));put(d,"inputs",inputs);put(d,"model",modelDict(m));put(d,"solve",S(m.magnetic()?"SolveMag":"SolveEle"));put(d,"post",S(m.magnetic()?"MapMag":"MapEle"));return d;}
struct Cell{long long id,region;std::array<long long,3>nodes;std::array<V,3>vertices;double area;};
struct Mesh{std::map<long long,V>nodes;std::vector<Cell>cells;};
Key geometryKey(std::array<V,3>v){std::sort(v.begin(),v.end());Key k;size_t n=0;for(auto&p:v)for(double a:p){if(!std::isfinite(a)||std::abs(a)>4)throw std::runtime_error("POS/mesh geometry exceeds validated model coordinate bounds");k[n++]=llround(a*1e10);}return k;}
std::string bounded(Tcl_Interp*ip,Tcl_Obj*d,const char*name){auto p=get(ip,d,name);if(!p)throw std::runtime_error(std::string("Missing typed solver output role: ")+name);int n=0;const char*data=Tcl_GetStringFromObj(p,&n);if(n<1||n>64*1024*1024)throw std::runtime_error("Solver output exceeds bounded parser capacity");return std::string(data,n);}
Mesh readMesh(const std::string&s){std::istringstream in(s);std::string line;Mesh m;bool format=false,nodes=false,elements=false;size_t count;std::set<long long>ids;while(std::getline(in,line)){if(line=="$MeshFormat"){if(!std::getline(in,line)||line!="2.2 0 8")throw std::runtime_error("Require exact ASCII Gmsh MSH2.2 doubles");format=true;}else if(line=="$Nodes"){if(nodes||!(in>>count)||count<3||count>60000)throw std::runtime_error("Invalid/duplicate mesh node section");std::getline(in,line);for(size_t i=0;i<count;++i){if(!std::getline(in,line))throw std::runtime_error("Truncated mesh nodes");std::istringstream row(line);long long id;V v;std::string extra;if(!(row>>id>>v[0]>>v[1]>>v[2])||id<1||row>>extra||!std::isfinite(v[0])||!std::isfinite(v[1])||!std::isfinite(v[2])||std::abs(v[2])>1e-12||!m.nodes.emplace(id,v).second)throw std::runtime_error("Invalid/nonplanar/duplicate mesh node");}nodes=true;}else if(line=="$Elements"){if(!nodes||elements||!(in>>count)||count>150000)throw std::runtime_error("Invalid mesh element section");std::getline(in,line);for(size_t i=0;i<count;++i){if(!std::getline(in,line))throw std::runtime_error("Truncated mesh elements");std::istringstream row(line);long long id;int type,tags;if(!(row>>id>>type>>tags)||id<1||tags<0||tags>16||!ids.insert(id).second)throw std::runtime_error("Invalid mesh element header");long long region=0,tag;for(int j=0;j<tags;++j){if(!(row>>tag))throw std::runtime_error("Truncated mesh tags");if(j==0)region=tag;}if(type!=2){if(type!=1&&type!=15)throw std::runtime_error("Unsupported non-triangle mesh element");continue;}Cell c;c.id=id;c.region=region;if(tags<1||(region!=101&&region!=102))throw std::runtime_error("Unexpected triangle physical region");for(size_t j=0;j<3;++j){if(!(row>>c.nodes[j])||!m.nodes.count(c.nodes[j]))throw std::runtime_error("Unknown triangle node identity");c.vertices[j]=m.nodes.at(c.nodes[j]);}std::string extra;if(row>>extra||c.nodes[0]==c.nodes[1]||c.nodes[1]==c.nodes[2]||c.nodes[0]==c.nodes[2])throw std::runtime_error("Malformed triangle connectivity");auto&a=c.vertices[0];auto&b=c.vertices[1];auto&d=c.vertices[2];c.area=((b[0]-a[0])*(d[1]-a[1])-(d[0]-a[0])*(b[1]-a[1]))/2;if(!(c.area>0))throw std::runtime_error("Triangle must have positive planar orientation and nonzero area");m.cells.push_back(c);if(m.cells.size()>30000)throw std::runtime_error("Triangle capacity exceeded");}elements=true;}}
 if(!format||!nodes||!elements||m.cells.size()<3)throw std::runtime_error("Incomplete mesh topology");return m;}
struct Field{std::array<V,3>values;std::array<V,3>vertices;};
class Cursor{const std::string&s;size_t p;public:Cursor(const std::string&s,size_t p):s(s),p(p){}void ch(char c){while(p<s.size()&&isspace((unsigned char)s[p]))++p;if(p==s.size()||s[p++]!=c)throw std::runtime_error("Malformed native POS grammar");}double num(){while(p<s.size()&&isspace((unsigned char)s[p]))++p;char*end;double v=strtod(s.c_str()+p,&end);if(end==s.c_str()+p||!std::isfinite(v))throw std::runtime_error("Nonfinite/malformed native POS value");p=end-s.c_str();return v;}size_t pos()const{return p;}};
std::map<Key,Field>readPOS(const std::string&s,bool vector){std::map<Key,Field>out;size_t at=0;std::string marker=vector?"VT":"ST";while((at=s.find(marker,at))!=std::string::npos){Cursor c(s,at+2);c.ch('(');std::array<V,3>verts;for(size_t i=0;i<9;++i){verts[i/3][i%3]=c.num();if(i<8)c.ch(',');}c.ch(')');c.ch('{');Field f{};size_t count=vector?9:3;for(size_t i=0;i<count;++i){if(vector)f.values[i/3][i%3]=c.num();else f.values[i][0]=c.num();if(i+1<count)c.ch(',');}c.ch('}');c.ch(';');f.vertices=verts;if(!out.emplace(geometryKey(verts),f).second)throw std::runtime_error("Duplicate finite-element field geometry");if(out.size()>30000)throw std::runtime_error("Field cell budget exceeded");at=c.pos();}if(out.empty())throw std::runtime_error("No required triangular native field values");return out;}
void append(Tcl_Obj*d,const char*k,Tcl_Obj*v){Tcl_Obj*l=nullptr;Tcl_DictObjGet(nullptr,d,S(k),&l);if(!l){l=Tcl_NewListObj(0,nullptr);put(d,k,l);}Tcl_ListObjAppendElement(nullptr,l,v);}
Tcl_Obj*parse(Tcl_Interp*ip,const Model&m,Tcl_Obj*files){auto mesh=readMesh(bounded(ip,files,"mesh"));for(auto&[id,p]:mesh.nodes)if(std::abs(p[0])>m.half+1e-9||std::abs(p[1])>m.height/2+1e-9)throw std::runtime_error("Mesh node lies outside the actual declared model domain");auto scalar=readPOS(bounded(ip,files,"scalar"),false),vector=readPOS(bounded(ip,files,"vector"),true);if(mesh.cells.size()!=scalar.size()||mesh.cells.size()!=vector.size())throw std::runtime_error("Exact mesh/field cell counts differ");std::map<Key,Field>auxiliary;if(m.magnetic()){auxiliary=readPOS(bounded(ip,files,"auxiliary"),true);if(auxiliary.size()!=mesh.cells.size())throw std::runtime_error("H field/topology mismatch");}auto nodes=Tcl_NewDictObj(),cells=Tcl_NewDictObj(),receipt=Tcl_NewDictObj();for(auto&[id,p]:mesh.nodes){append(nodes,"node_id",Tcl_NewWideIntObj(id));for(int i=0;i<3;++i)append(nodes,i==0?"x":i==1?"y":"z",Tcl_NewDoubleObj(p[i]));}
 std::map<long long,double>potential,residual,forcing,boundary;double conductorArea=0,maxEError=0,sumESquare=0,maxGradientError=0;std::vector<V>fieldValues;for(auto&c:mesh.cells){auto key=geometryKey(c.vertices);if(!scalar.count(key)||!vector.count(key))throw std::runtime_error("Field topology does not match complete mesh");auto a=scalar.at(key),v=vector.at(key);Field ordered=a;for(size_t j=0;j<3;++j){bool found=false;for(size_t k=0;k<3;++k)if(std::hypot(c.vertices[j][0]-a.vertices[k][0],c.vertices[j][1]-a.vertices[k][1])<1e-9){ordered.values[j]=a.values[k];found=true;break;}if(!found)throw std::runtime_error("Scalar nodal geometry mismatch");}a=ordered;if(!m.magnetic()&&c.region!=101)throw std::runtime_error("Unexpected electrostatic material region");V f{},centroid{};double phi=0;for(size_t j=0;j<3;++j){phi+=a.values[j][0]/3;for(int k=0;k<3;++k){centroid[k]+=c.vertices[j][k]/3;f[k]+=v.values[j][k]/3;}auto [it,inserted]=potential.emplace(c.nodes[j],a.values[j][0]);if(!inserted&&std::abs(it->second-a.values[j][0])>1e-8*std::max(1.,std::abs(it->second)))throw std::runtime_error("Inconsistent shared-node scalar potential");}fieldValues.push_back(f);append(cells,"element_id",Tcl_NewWideIntObj(c.id));append(cells,"region_id",Tcl_NewWideIntObj(c.region));append(cells,"material_id",Tcl_NewWideIntObj(c.region));for(int j=0;j<3;++j){append(cells,j==0?"node_0_id":j==1?"node_1_id":"node_2_id",Tcl_NewWideIntObj(c.nodes[j]));append(cells,j==0?"x":j==1?"y":"z",Tcl_NewDoubleObj(centroid[j]));append(cells,j==0?"field_x":j==1?"field_y":"field_z",Tcl_NewDoubleObj(f[j]));}if(m.magnetic()){if(!auxiliary.count(key))throw std::runtime_error("H field geometry mismatch");auto h=auxiliary.at(key);for(int k=0;k<3;++k)append(cells,k==0?"auxiliary_x":k==1?"auxiliary_y":"auxiliary_z",Tcl_NewDoubleObj((h.values[0][k]+h.values[1][k]+h.values[2][k])/3));}append(cells,"potential",Tcl_NewDoubleObj(phi));append(cells,"field_norm",Tcl_NewDoubleObj(std::hypot(f[0],std::hypot(f[1],f[2]))));append(cells,"area",Tcl_NewDoubleObj(c.area));if(c.region==102)conductorArea+=c.area;
 // Independent linear-triangle weak residual from actual nodal FEM output.
 double b[3],g[3];for(int i=0;i<3;++i){int j=(i+1)%3,k=(i+2)%3;b[i]=(c.vertices[j][1]-c.vertices[k][1])/(2*c.area);g[i]=(c.vertices[k][0]-c.vertices[j][0])/(2*c.area);}double gradientX=0,gradientY=0;for(int i=0;i<3;++i){gradientX+=b[i]*a.values[i][0];gradientY+=g[i]*a.values[i][0];}V expected=m.magnetic()?V{gradientY,-gradientX,0}:V{-gradientX,-gradientY,0};double error=std::hypot(f[0]-expected[0],std::hypot(f[1]-expected[1],f[2]))/std::max(1e-12,std::hypot(expected[0],expected[1]));maxGradientError=std::max(maxGradientError,error);if(error>1e-6)throw std::runtime_error("Computed vector field disagrees with actual nodal potential gradient");double coefficient=m.magnetic()?1/(mu0*(c.region==102?m.mur:1)):eps0*m.epsr;for(int i=0;i<3;++i){double force=m.magnetic()&&c.region==102?m.j*c.area/3:0;forcing[c.nodes[i]]+=force;residual[c.nodes[i]]-=force;for(int j=0;j<3;++j){double stiffness=coefficient*c.area*(b[i]*b[j]+g[i]*g[j]);residual[c.nodes[i]]+=stiffness*a.values[j][0];auto p=c.vertices[j];bool fixed=m.magnetic()?std::abs(std::abs(p[0])-m.half)<1e-9||std::abs(std::abs(p[1])-m.height/2)<1e-9:std::abs(std::abs(p[0])-m.half)<1e-9;if(fixed)boundary[c.nodes[i]]+=stiffness*a.values[j][0];}}
 if(!m.magnetic()){double expected=-m.voltage/(2*m.half),error=std::hypot(f[0]-expected,std::hypot(f[1],f[2]))/std::abs(expected);maxEError=std::max(maxEError,error);sumESquare+=error*error*c.area;}}
 double totalArea=0;for(auto&c:mesh.cells)totalArea+=c.area;if(std::abs(totalArea-2*m.half*m.height)>1e-8*2*m.half*m.height||m.magnetic()&&!(conductorArea>0))throw std::runtime_error("Exact mesh does not cover modeled domain/material");for(auto&[id,p]:mesh.nodes){if(!potential.count(id))throw std::runtime_error("Mesh node is missing its actual scalar potential");append(nodes,"potential",Tcl_NewDoubleObj(potential.at(id)));}double norm=0,scale=0;size_t free=0;for(auto&[id,p]:mesh.nodes){bool fixed=m.magnetic()?std::abs(std::abs(p[0])-m.half)<1e-9||std::abs(std::abs(p[1])-m.height/2)<1e-9:std::abs(std::abs(p[0])-m.half)<1e-9;if(fixed)continue;++free;norm+=residual[id]*residual[id];double v=forcing[id]-boundary[id];scale+=v*v;}double relative=sqrt(norm/std::max(scale,1e-300));if(!std::isfinite(relative))throw std::runtime_error("Nonfinite independently assembled weak residual");std::string log=bounded(ip,files,"solver_log");size_t mark=log.find("GXTXT_RESIDUAL ");if(mark==std::string::npos)throw std::runtime_error("GetDP did not supply the requested real residual receipt");std::istringstream residualLine(log.substr(mark+15));double solverResidual;if(!(residualLine>>solverResidual)||!std::isfinite(solverResidual)||solverResidual<0)throw std::runtime_error("Malformed actual GetDP residual");
 put(receipt,"max_field_gradient_relative_error",Tcl_NewDoubleObj(maxGradientError));put(receipt,"solver_residual_absolute",Tcl_NewDoubleObj(solverResidual));put(receipt,"independent_relative_weak_residual",Tcl_NewDoubleObj(relative));put(receipt,"free_nodes",Tcl_NewWideIntObj(free));put(receipt,"mesh_nodes",Tcl_NewWideIntObj(mesh.nodes.size()));put(receipt,"mesh_triangles",Tcl_NewWideIntObj(mesh.cells.size()));put(receipt,"field_association",S("cell_centroid; exact piecewise-constant first-order vector field; scalar is nodal average"));put(receipt,"kind",S(m.kind));put(receipt,"node_potential_unit",S(m.magnetic()?"Wb/m":"V"));put(receipt,"field_unit",S(m.magnetic()?"T":"V/m"));if(!m.magnetic()){put(receipt,"analytic_max_relative_field_error",Tcl_NewDoubleObj(maxEError));put(receipt,"analytic_area_rms_relative_field_error",Tcl_NewDoubleObj(sqrt(sumESquare/(2*m.half*m.height))));}else{put(receipt,"mesh_current_A",Tcl_NewDoubleObj(m.j*conductorArea));put(receipt,"nominal_circle_current_A",Tcl_NewDoubleObj(m.j*pi*m.r*m.r));double loop=0;size_t missing=0;const int samples=720;double radius=m.r*1.5;for(int k=0;k<samples;++k){double theta=2*pi*(k+.5)/samples,x=radius*cos(theta),y=radius*sin(theta);bool found=false;for(size_t i=0;i<mesh.cells.size();++i){auto&c=mesh.cells[i];auto&a=c.vertices[0];auto&b=c.vertices[1];auto&d=c.vertices[2];double u=((b[0]-x)*(d[1]-y)-(d[0]-x)*(b[1]-y))/(2*c.area),v=((d[0]-x)*(a[1]-y)-(a[0]-x)*(d[1]-y))/(2*c.area);if(u>=-1e-10&&v>=-1e-10&&u+v<=1+1e-10){auto f=fieldValues[i];loop+=(-sin(theta)*f[0]+cos(theta)*f[1])*radius*2*pi/samples;found=true;break;}}if(!found)++missing;}if(missing)throw std::runtime_error("Ampere reference loop leaves exact published mesh");put(receipt,"ampere_loop_T_m",Tcl_NewDoubleObj(loop));put(receipt,"ampere_mesh_expected_T_m",Tcl_NewDoubleObj(mu0*m.j*conductorArea));put(receipt,"ampere_mesh_relative_error",Tcl_NewDoubleObj(std::abs(loop-mu0*m.j*conductorArea)/std::abs(mu0*m.j*conductorArea)));}
 auto result=Tcl_NewDictObj();put(result,"nodes",nodes);put(result,"cells",cells);put(result,"receipt",receipt);return result;}
int command(ClientData,Tcl_Interp*ip,int n,Tcl_Obj*const v[]){try{if(n<2)throw std::runtime_error("Expected native EM operation");std::string op=Tcl_GetString(v[1]);if(op=="default"){if(n!=3)throw std::runtime_error("Expected problem kind");Model m;m.kind=Tcl_GetString(v[2]);if(m.kind!="magnetostatic_2d"&&m.kind!="electrostatic_2d")throw std::runtime_error("Unsupported problem kind");m.id=m.magnetic()?"em_conductor":"em_electrodes";m.half=.02;m.height=.04;m.h=m.magnetic()?.0015:.004;Tcl_SetObjResult(ip,modelDict(m));return TCL_OK;}if(n<3)throw std::runtime_error("Expected typed scientific model");auto m=model(ip,v[2]);if(op=="validate"){Tcl_SetObjResult(ip,modelDict(m));return TCL_OK;}if(op=="prepare"){Tcl_SetObjResult(ip,prepare(m));return TCL_OK;}if(op=="parse"&&n==4){Tcl_SetObjResult(ip,parse(ip,m,v[3]));return TCL_OK;}throw std::runtime_error("Unknown native EM operation");}catch(const std::exception&e){Tcl_SetObjResult(ip,S(e.what()));Tcl_SetErrorCode(ip,"GXTXT","ElectromagneticSimulation","Native",nullptr);return TCL_ERROR;}}
}
extern "C" int Emfem_Init(Tcl_Interp*ip){if(!Tcl_InitStubs(ip,"8.6",0))return TCL_ERROR;Tcl_EvalEx(ip,"namespace eval ::GX::EMNative {}",-1,TCL_EVAL_GLOBAL);Tcl_CreateObjCommand(ip,"::GX::EMNative::core",command,nullptr,nullptr);return Tcl_PkgProvide(ip,"GXTXT_EM_NATIVE","1.0");}
